/**
 * Hand-written flavour for every industry. The generator (catalog/generator.ts)
 * expands each compact row into a full IndustryDef + 8 ProductDefs.
 *
 * Row format (all strings, '|' separated lists):
 *   cat        category id (see categories.ts)
 *   name, emoji, color
 *   places     4 workplace tiers, smallest first
 *   products   8 products "Name:emoji", cheapest first (tiers Basic..Legendary)
 *   needs      commodity ids this industry consumes (comma separated)
 *   supplies   commodity ids this industry produces (comma separated, may be '')
 *   workers    2 industry-specific worker archetypes "Name:emoji:bio"
 *   upgrade    "Name:emoji:description"
 *   jokes      2+ industry jokes
 *   event      "Title:emoji:text"
 *   contract   "Title:Client:emoji:blurb"
 */
export type IndustryRow = [
  cat: string,
  name: string,
  emoji: string,
  color: string,
  places: string,
  products: string,
  needs: string,
  supplies: string,
  workers: string,
  upgrade: string,
  jokes: string,
  event: string,
  contract: string,
];

